```js
export function createMetrics() {
  const samples = new Map();
  return {
    record(name, ms) {
      const current = samples.get(name) ?? { count: 0, total: 0 };
      current.count += 1;
      current.total += ms;
      samples.set(name, current);
    },
    summary() {
      const result = {};
      for (const [name, { count, total }] of samples) {
        result[name] = { count, avgMs: Math.round(total / count) };
      }
      return result;
    },
  };
}
```

